#!/bin/sh
# Regenerate the C binding of every Omega unit linked into the C build (UNITS below), or with --check
# confirm the committed files are exactly what the pinned tools produce (exit 1 on any difference,
# 3 NOT_RUN without tools).
#   OMEGA_OMC     seed-born omc (OM-1 and OM-2 units), sha256 pinned below
#   OMEGA_BRIDGE  an aien-dev/omega-bridge checkout (om/omega-bridge.lock); src/native.om sha256 pinned below
# Generated by the bridge's src/native.om (docs/NATIVE-ABI.md: ABI v1 for OM-1 units, v2 for OM-2 units):
#   src/omega_om_units.c      every unit's machine code, byte for byte as omc wrote it, and its binding
#                             (output c), then the C API functions of the OM-2 units, out of line
#                             (output apic: e.g. sha256_init calls omega2_sha256_init, abort() on a
#                             nonzero status)
#   src/omega_native.h        the bindings' declarations (h)
#   src/omega_api_decl.h      the C API of the OM-2 units, declarations only: layouts as C structs with
#                             static-asserted offsets, defines, prototypes (apih; src/sha256.h includes it)
#   src/omega_om_units.ident  each unit's identity: source sha256, compiler pin, ABI, profile. An OM-2
#                             unit also embeds its identity (omega2_ident_<unit>() in omega_om_units.c).
#   src/omega_om_units_fs.c   the freestanding binding of the FS_UNITS below for the -ffreestanding GPU link
#                             (mk/omega-gpu-engine.mk GPU_FS_SRCS): output freest (machine code and ABI v2 on
#                             the caller's stack; no thread-local state, heap, stack mapping or abort; only
#                             memset and memmove) then output fapic (the same C API as apic, __builtin_trap()
#                             on a nonzero status). Its declarations are those of omega_api_decl.h.
# A unit, compiler or profile that changes without regenerating these files fails --check.
# OMEGA_UNITS (the unit list, repo-relative or absolute) and OMEGA_UNITS_DEST (output directory, default src)
# override the defaults; mk/om-encoder.mk uses them to build mutant encoders beside the real binding.
set -eu
OMC_PIN=210c52566e782cf15ece6e478d45bfb67f1ad338f29e41546dad9b6c4f85b54c
NATIVE_PIN=9788b27a92c8dd365de7052439653de62f89634189a34cb6b3f582cae65dda83
ROOT=$(cd "$(dirname "$0")/.." && pwd)
# One generated library for all units: the bindings share one ABI runtime (ombr_enter).
# om/encoder/bw_enc_sm121.om: the sm_121 instruction encoder, twin of aien-dev/CUDApp's (mk/om-encoder.mk).
UNITS="${OMEGA_UNITS:-om/arboris_arena.om om/arboris_spread.om om/arboris_gated.om om/blackwell_arboris_emit.om om/blackwell_arboris_qmd.om gpu/nvidia/om/codegen/bw_hazard.om om/sha256/sha256-om2.om om/blake3/b3unit.om om/encoder/bw_enc_sm121.om om/gpu/bw_qmd.om om/gpu/bw_sched.om om/gpu/bw_regalloc.om om/gpu/bw_vecadd.om om/gpu/cg_matmul.om om/gpu/cg_gpu_gemm.om om/gpu/cg_gpu_attn.om om/gpu/q38_plan.om om/gpu/moe_plan.om om/gpu/cg_pf.om om/gpu/cg_bf16.om om/gpu/cg_gemm.om om/gpu/cg_moe2.om om/gpu/cg_moe.om om/gpu/cg_qmma.om om/gpu/cg_pfhost.om om/gpu/cg_tgemm.om om/gpu/cg_tc2.om om/gpu/cg_qg.om om/gpu/cg_tc.om om/gpu/cg_pattn256.om om/gpu/cg_router.om om/gpu/cg_pattn.om om/gpu/cg_attn.om om/gpu/cg_tern.om om/gpu/cg_attn256.om om/gpu/cg_dec.om om/gpu/cg_gdn.om om/runtime/rx_regulate.om om/runtime/rx_mid.om om/runtime/rx_cortex_rec.om om/runtime/rx_plan_core.om om/runtime/rx_projection.om om/runtime/rx_capq_core.om om/runtime/rx_costmodel_core.om om/runtime/rx_route_core.om om/runtime/rx_world_core.om om/runtime/rx_skillroute_core.om om/runtime/rx_fusion_core.om om/compiler/osc_literal.om om/compiler/osc_type.om om/compiler/osc_expr.om om/compiler/osc_scalar.om om/compiler/osc_a64_fields.om om/compiler/osc_statement.om om/compiler/osc_ownership.om om/compiler/osc_scope.om om/compiler/osc_pool.om om/compiler/osc_trace.om om/compiler/osc_lifetimes.om om/compiler/osc_flow.om om/compiler/osc_artifact.om src/tensor/tensor_shape.om src/tensor/tensor_ops.om src/train/sgd_update.om src/train/generation.om src/autodiff/gradient_shape.om src/allen/allen_core.om src/path/rx_path_core.om src/ans/ans_core.om src/reservoir/reservoir_readout.om src/crumbline/cl_core.om src/dual/rx_dual_core.om src/dual_experiment/applic_core.om src/estimation/est_core.om}"
# The units the freestanding GPU link needs (the encoder, codegen, matmul and realize files hash with sha256_*; qmd packs QMDs; regalloc solves intervals; bw_vecadd emits vecadd; cg_matmul emits tensor/frag/i32 IR).
FS_UNITS="om/sha256/sha256-om2.om om/gpu/bw_qmd.om om/gpu/bw_regalloc.om om/gpu/bw_vecadd.om om/gpu/cg_matmul.om om/gpu/cg_gpu_attn.om"
DEST="${OMEGA_UNITS_DEST:-$ROOT/src}"
OUTS="omega_om_units.c omega_native.h omega_api_decl.h omega_om_units.ident omega_om_units_fs.c"
[ -n "${OMEGA_OMC:-}" ] && [ -n "${OMEGA_BRIDGE:-}" ] || { echo "NOT_RUN: set OMEGA_OMC and OMEGA_BRIDGE"; exit 3; }
[ "$(sha256sum < "$OMEGA_OMC" | cut -c1-64)" = "$OMC_PIN" ] || { echo "NOT_RUN: omc is not the pinned compiler"; exit 3; }
[ "$(sha256sum < "$OMEGA_BRIDGE/src/native.om" | cut -c1-64)" = "$NATIVE_PIN" ] || { echo "NOT_RUN: native.om is not the pinned generator"; exit 3; }
T=$(mktemp -d); trap 'rm -rf "$T"' EXIT
"$OMEGA_OMC" < "$OMEGA_BRIDGE/src/native.om" > "$T/native"; chmod +x "$T/native"
: > "$T/units.in"; : > "$T/host.in"; : > "$T/leaf.in"; : > "$T/fs.in"; : > "$T/omega_om_units.ident"
for u in $UNITS; do
  case "$u" in /*) src=$u ;; *) src=$ROOT/$u ;; esac
  # One callable unit for the ontology, loader and CPU step. Its identity
  # covers the exact ordered source bytes the compiler and generator consume.
  if [ "$src" -ef "$ROOT/om/arboris_spread.om" ]; then
    cat "$ROOT/om/arboris_ontology.om" "$ROOT/om/tls/sha2.om" "$ROOT/om/arboris_records.om" "$src" > "$T/arboris_spread.om"
    src="$T/arboris_spread.om"
  fi
  if [ "$src" -ef "$ROOT/om/arboris_gated.om" ]; then
    # The vector oracle reuses the arena planner and E1 floating-point
    # reference. Only the tick is exported by this combined unit.
    sed 's/^export fn /fn /' "$ROOT/om/arboris_arena.om" > "$T/arboris_gated.om"
    cat "$ROOT/gpu/nvidia/om/numeric/numeric.om" "$src" >> "$T/arboris_gated.om"
    src="$T/arboris_gated.om"
  fi
  if [ "$src" -ef "$ROOT/om/blackwell_arboris_emit.om" ]; then
    { echo om2; cat "$ROOT/om/encoder/bw_enc_sm121.om" "$src" "$ROOT/om/blackwell_arboris_gated_emit.om"; } > "$T/blackwell_arboris_emit.om"
    src="$T/blackwell_arboris_emit.om"
  fi
  if [ "$src" -ef "$ROOT/om/blackwell_arboris_qmd.om" ]; then
    sed 's/^export fn /fn /' "$ROOT/om/gpu/bw_qmd.om" > "$T/blackwell_arboris_qmd.om"
    cat "$src" >> "$T/blackwell_arboris_qmd.om"
    src="$T/blackwell_arboris_qmd.om"
  fi
  if [ "$src" -ef "$ROOT/gpu/nvidia/om/codegen/bw_hazard.om" ]; then
    { echo om2; sed 's/^fn hz_chk /export fn hz_chk /' "$src"; } > "$T/bw_hazard.om"
    src="$T/bw_hazard.om"
  fi
  name=$(basename "$u" .om | tr -c 'A-Za-z0-9_\n' '_')
  "$OMEGA_OMC" < "$src" > "$T/u.bin"
  # The profile: OM-2 iff the first line that is neither a note nor blank is exactly om2 (erratum E10).
  if [ "$(sed -n '/^ *note\( \|$\)/d; /^ *$/d; p; q' "$src")" = om2 ]; then abi=2; prof=OM-2; else abi=1; prof=OM-1; fi
  { cat "$src"; printf '\0'; printf '%08d' "$(wc -c < "$T/u.bin")"; cat "$T/u.bin"
    [ $abi = 1 ] || printf 'omega-unit %s %s\n' "$name" "$OMC_PIN"; } > "$T/u.in"
  cat "$T/u.in" >> "$T/units.in"
  if [ "$src" = "$T/blackwell_arboris_emit.om" ] || [ "$src" = "$T/blackwell_arboris_qmd.om" ] || [ "$src" = "$T/arboris_spread.om" ] || [ "$src" -ef "$ROOT/om/arboris_arena.om" ] || [ "$src" -ef "$ROOT/src/tensor/tensor_shape.om" ] || [ "$src" -ef "$ROOT/om/compiler/osc_flow.om" ] ||
     [ "$src" -ef "$ROOT/src/train/generation.om" ] || [ "$src" -ef "$ROOT/om/compiler/osc_statement.om" ] ||
     [ "$src" -ef "$ROOT/om/compiler/osc_artifact.om" ] || [ "$src" -ef "$ROOT/src/autodiff/gradient_shape.om" ]; then
    cat "$T/u.in" >> "$T/leaf.in"
  else
    cat "$T/u.in" >> "$T/host.in"
  fi
  case " $FS_UNITS " in *" $u "*) cat "$T/u.in" >> "$T/fs.in";; esac
  echo "omega-ident 1 unit=$name abi=$abi profile=$prof src=$(sha256sum < "$src" | cut -c1-64) omc=$OMC_PIN path=$u" >> "$T/omega_om_units.ident"
done
: > "$T/omega_om_units.c"
if [ -s "$T/host.in" ]; then
  { "$T/native" c < "$T/host.in"; "$T/native" apic < "$T/host.in"; } > "$T/omega_om_units.c"
fi
# Bounded leaf units use the generator's caller-stack ABI. Namespace its private
# helpers (including assembly labels) so the two generated bindings can share
# one translation unit. Public entry points and embedded code stay unchanged.
if [ -s "$T/leaf.in" ]; then
  "$T/native" freest < "$T/leaf.in" > "$T/leaf.c"
  "$T/native" fapic < "$T/leaf.in" >> "$T/leaf.c"
  # Match a private identifier at a token or embedded assembly line boundary.
  # The equals sign in "unit=<name>" belongs to the identity string.
  sed -E 's/(^|\\n|[^[:alnum:]_=])ombr(2?_[[:alnum:]_]+)/\1ombr_leaf\2/g' "$T/leaf.c" >> "$T/omega_om_units.c"
fi
"$T/native" h < "$T/units.in" > "$T/omega_native.h"
"$T/native" apih < "$T/units.in" > "$T/omega_api_decl.h"
if [ -s "$T/fs.in" ]; then
  { "$T/native" freest < "$T/fs.in"; "$T/native" fapic < "$T/fs.in"; } > "$T/omega_om_units_fs.c"
else
  echo '/* No freestanding GPU units selected. */' > "$T/omega_om_units_fs.c"
fi
if [ "${1:-}" = --check ]; then
  bad=0
  for f in $OUTS; do cmp -s "$T/$f" "$DEST/$f" || { echo "FAIL $DEST/$f differs from the pinned tools' output"; bad=1; }; done
  [ $bad = 0 ] || exit 1
  echo "PASS src/{$(echo $OUTS | tr ' ' ,)} regenerate byte for byte"; exit 0
fi
for f in $OUTS; do cp "$T/$f" "$DEST/$f"; done; echo "wrote $DEST/{$(echo $OUTS | tr ' ' ,)}"
